"$HOME/.opal/.venv/bin/python" -c 'import json, os, pathlib, subprocess, sys
try:
    event = json.load(sys.stdin)
except Exception:
    event = {}
if event.get("stop_hook_active"):
    sys.exit(0)
cwd = pathlib.Path(event.get("cwd") or os.getcwd()).resolve()
seen = set()
candidates = []
def add_task(path):
    try:
        task = pathlib.Path(path).resolve()
    except Exception:
        return
    key = str(task)
    if key in seen:
        return
    seen.add(key)
    state_file = task / "state.json"
    if not state_file.is_file():
        return
    try:
        state = json.loads(state_file.read_text(encoding="utf-8"))
    except Exception:
        return
    if state.get("current_status") in ("in_progress", "blocked"):
        candidates.append((state.get("updated_at", ""), task))
declared = False
for env_name in ("OPAL_TASK_PATH", "OPAL_ACTIVE_TASK_PATH"):
    if os.environ.get(env_name):
        declared = True
        add_task(os.environ[env_name])
# 세션이 자기 태스크를 명시했으면 그것만 판정한다(135 ADD-1).
# 명시한 태스크가 활성이 아니면 이어갈 것이 없다는 뜻이므로 차단하지 않는다.
# 디스크 스캔은 명시가 없을 때의 폴백이며, 다른 PM이 관리하는 더 최근 태스크를
# updated_at 정렬로 집어 이 세션을 밀어붙이는 오작동을 막는다.
for base in (cwd, *cwd.parents) if not declared else ():
    add_task(base)
    tasks_dir = base / "tasks"
    if tasks_dir.is_dir():
        try:
            for child in tasks_dir.iterdir():
                if child.is_dir() and not child.is_symlink():
                    add_task(child)
        except Exception:
            pass
    meta_dir = base / ".opal-worktrees" / ".meta"
    if meta_dir.is_dir():
        try:
            for meta_file in meta_dir.glob("task_*.json"):
                try:
                    meta = json.loads(meta_file.read_text(encoding="utf-8"))
                    if isinstance(meta.get("task_path"), str):
                        add_task(meta["task_path"])
                except Exception:
                    pass
        except Exception:
            pass
if not candidates:
    sys.exit(0)
candidates.sort(key=lambda item: (item[0], item[1].name), reverse=True)
run_sh = pathlib.Path.home() / ".opal" / "tools" / "state-tool" / "run.sh"
try:
    out = subprocess.check_output([str(run_sh), "show", str(candidates[0][1]), "--format", "json"], text=True, timeout=5)
    payload = json.loads(out.strip().splitlines()[-1])
except Exception:
    sys.exit(0)
if payload.get("transition_action") == "continue":
    next_action = payload.get("next_action") or "다음 파이프라인 행 진행"
    reason = "OPAL active task is still transition_action=continue. Continue this run instead of ending the response. next_action: " + next_action
    print(json.dumps({"decision": "block", "reason": reason}, ensure_ascii=False))
'
